function summarizeWindow(events, nowMs, windowMs, cap) {
  const seenIds = new Set();
  const deduped = [];
  const input = Array.isArray(events) ? events : [];

  for (let i = 0; i < input.length; i++) {
    const ev = input[i];
    const id = ev && typeof ev === "object" ? ev.id : undefined;
    if (typeof id === "string" && id !== "") {
      if (seenIds.has(id)) continue;
      seenIds.add(id);
    }
    deduped.push(ev);
  }

  const windowStart = nowMs - windowMs;
  let used = 0;
  let minTs = Infinity;
  const counts = Object.create(null);

  for (let i = 0; i < deduped.length; i++) {
    const ev = deduped[i];
    if (!ev || typeof ev !== "object") continue;

    const ts = ev.ts;
    if (typeof ts !== "number" || !Number.isFinite(ts)) continue;
    if (ts < windowStart || ts > nowMs) continue;

    if (ev.provider !== "opencode-go") continue;
    if (ev.error) continue;

    if (typeof ev.model !== "string") continue;
    if (ev.model.toLowerCase().endsWith("-free")) continue;

    used += 1;
    if (ts < minTs) minTs = ts;

    let name = ev.model;
    if (name.toLowerCase().startsWith("opencode-go/")) {
      name = name.slice("opencode-go/".length);
    }
    name = name.toLowerCase();

    counts[name] = (counts[name] || 0) + 1;
  }

  const byModel = {};
  const keys = Object.keys(counts).sort();
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    byModel[key] = counts[key];
  }

  return {
    used,
    remaining: Math.max(0, cap - used),
    pct: Math.round((used / cap) * 1000) / 10,
    overCap: used > cap,
    oldestExpiresAt: used === 0 ? null : minTs + windowMs,
    byModel,
  };
}
